import {readState,mutate,event,sessionOf} from './state.js?v=5.1.0';
const uid=p=>p+'-'+crypto.randomUUID();
export const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const defaults=s=>{s.manager??={profileName:'',stage:'signup',completed:false,messages:[]};s.manager.messages??=[];s.reservations??=[];s.inventory??=[];s.staffTasks??=[];s.store.media??=[];for(const v of s.sessions){v.thread??=[];v.points??=0;v.pointLedger??=[];}return s;};
export function conversationState(){return defaults(readState())}
export function change(fn){return mutate(s=>fn(defaults(s)))}
export function thread(role,id){const s=conversationState();return role==='owner'?s.manager.messages:sessionOf(s,id)?.thread||[]}
export function addMessage(role,id,message){return change(s=>{const list=role==='owner'?s.manager.messages:sessionOf(s,id).thread;const m={id:uid('chat'),at:new Date().toISOString(),seq:(list.at(-1)?.seq||list.length)+1,...message};list.push(m);if(list.length>200)list.splice(0,list.length-200);return m;})}
export function ownerSignup(name){return change(s=>{if(!name.trim())throw new Error('required');s.manager.profileName=name.trim().slice(0,40);s.manager.stage='name';return true;})}
export function saveSetup(step,value){return change(s=>{const next={name:'menu',menu:'venue',venue:'location',location:'contact',contact:'sns',sns:'review',review:'ready'};if(!next[step])throw new Error('invalid');if(step==='name'){if(!String(value.name||'').trim())throw new Error('required');s.store.name=value.name.trim().slice(0,50);}if(step==='location'){if(!String(value.address||'').trim())throw new Error('required');s.store.address=value.address.trim().slice(0,200);s.store.country=value.country||'VN';}if(step==='contact'){s.store.phone=String(value.phone||'').trim().slice(0,40);s.store.email=String(value.email||'').trim().slice(0,150);}if(step==='sns')s.store.website=String(value.website||'').trim().slice(0,250);s.manager.stage=next[step];if(step==='review'){if(!value.approved)throw new Error('approvalRequired');s.manager.completed=true;event(s,'eventStore',null,{name:s.store.name});}return next[step];})}
export function editStore(){change(s=>{s.manager.stage='name';s.manager.completed=false;})}
export function addMedia(records,kind){change(s=>{for(const m of records)s.store.media.push({...m,kind});s.store.media=s.store.media.slice(-30);})}
export function reserve(id,data,requestId){return change(s=>{const old=s.reservations.find(r=>r.requestId===requestId&&r.sessionId===id);if(old)return old;const size=Number(data.partySize),start=new Date(today()+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+31);const when=new Date(data.date+'T'+data.time);if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date||'')||!/^\d{2}:\d{2}$/.test(data.time||'')||!Number.isFinite(+when)||when.getFullYear()!==Number(data.date.slice(0,4))||when.getMonth()+1!==Number(data.date.slice(5,7))||when.getDate()!==Number(data.date.slice(8,10))||when<new Date()||when>=end||!Number.isInteger(size)||size<1||size>20||!String(data.name||'').trim())throw new Error('invalidBooking');const v=sessionOf(s,id);if(!v)throw new Error('invalidBooking');const r={id:uid('reservation'),number:s.reservations.length+1,sessionId:id,table:v.table,lang:v.lang,requestId,date:data.date,time:data.time,partySize:size,name:data.name.trim().slice(0,40),status:'pending',at:new Date().toISOString()};s.reservations.push(r);event(s,'eventBooking',id,{reservationId:r.id,date:r.date,time:r.time});return r;})}
export function updateReservation(id,status,sessionId){return change(s=>{const r=s.reservations.find(r=>r.id===id);if(!r||(sessionId&&r.sessionId!==sessionId)||!['confirmed','cancelled'].includes(status)||r.status==='cancelled')return false;if(r.status===status)return true;r.status=status;event(s,'eventBooking',r.sessionId,{reservationId:id,status});return true;})}
export function payOrder(orderId,sessionId){return change(s=>{const o=s.orders.find(o=>o.id===orderId);if(!o||(sessionId&&o.sessionId!==sessionId))throw new Error('noUnpaidOrders');const v=sessionOf(s,o.sessionId);if(!v)throw new Error('noUnpaidOrders');if(o.payment==='paid')return {order:o,added:0};o.payment='paid';const points=Math.floor(o.total/1000);o.pointsCredited=points;v.points+=points;v.pointLedger.push({id:uid('points'),amount:points,orderId:o.id,at:new Date().toISOString()});event(s,'eventStatus',o.sessionId,{orderId,payment:'paid',points});return {order:o,added:points};})}
export function redeemPoints(id){return change(s=>{const v=sessionOf(s,id);if(!v||v.points<100)throw new Error('notEnoughPoints');v.points-=100;const c={id:uid('coupon'),code:'JM-'+crypto.randomUUID().slice(-6).toUpperCase(),reward:'rewardSnack',source:'points',used:false,at:new Date().toISOString()};v.coupons.push(c);v.pointLedger.push({id:uid('points'),amount:-100,couponId:c.id,at:c.at});event(s,'eventReward',id,{reward:c.reward,source:'points'});return c;})}
export function saveInventory(data){return change(s=>{const name=String(data.name||'').trim(),quantity=Number(data.quantity),unit=String(data.unit||'').trim();if(!name||!unit||!Number.isFinite(quantity)||quantity<0||quantity>100000)throw new Error('required');let item=s.inventory.find(i=>i.name.toLowerCase()===name.toLowerCase());if(!item){item={id:uid('stock'),name:name.slice(0,60)};s.inventory.push(item);}item.quantity=quantity;item.unit=unit.slice(0,15);item.at=new Date().toISOString();return item;})}
export function saveTask(data){return change(s=>{const title=String(data.title||'').trim(),assignee=String(data.assignee||'').trim();if(!title||!assignee)throw new Error('required');const task={id:uid('task'),title:title.slice(0,120),assignee:assignee.slice(0,40),done:false,at:new Date().toISOString()};s.staffTasks.push(task);return task;})}
export function completeTask(id){change(s=>{const task=s.staffTasks.find(t=>t.id===id);if(task)task.done=true;})}
export function metrics(s=conversationState()){return {sales:s.orders.filter(o=>o.payment==='paid').reduce((n,o)=>n+o.total,0),orders:s.orders.length,bookings:s.reservations.filter(r=>r.status==='pending').length,requests:s.events.filter(e=>['complaint','eventStaff'].includes(e.type)&&!e.reviewed).length};}
const csvCell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
export function taxCsv(s=conversationState()){return '\uFEFF'+[['order_id','occurred_at','currency','amount','payment_status'],...s.orders.filter(o=>o.payment==='paid').map(o=>[o.id,o.at,'VND',o.total,'paid'])].map(row=>row.map(csvCell).join(',')).join('\r\n');}
